* {
    box-sizing: border-box;
}

body {
    background-color: var(--bg-color);
    color: var(--text-primary);
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    margin: 0;
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 100vh;
}

.container {
    background-color: var(--container-bg);
    padding: 2rem;
    border-radius: 8px;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.5);
    width: 100%;
    max-width: 450px;
}

h1 {
    margin-top: 0;
    font-size: 1.5rem;
    color: var(--accent-color);
}

.form-field {
    margin-bottom: 2rem;
}

fieldset {
    border: none;
    padding: 0;
    margin: 0;
}

legend {
    font-size: 1.1rem;
    font-weight: 600;
    margin-bottom: 0.5rem;
    display: block;
}

.required {
    color: var(--error-color);
    margin-left: 0.25rem;
}

.field-hint {
    font-size: 0.9rem;
    color: var(--text-secondary);
    margin-bottom: 1rem;
}

.radio-option {
    display: flex;
    align-items: center;
    margin-bottom: 0.75rem;
    padding: 0.5rem;
    border-radius: 4px;
    transition: background-color 0.2s;
    cursor: pointer;
}

.radio-option:hover {
    background-color: rgba(255, 255, 255, 0.05);
}

/* Custom radio styling to ensure it's "polished" while keeping native functionality */
input[type="radio"] {
    appearance: none;
    -webkit-appearance: none;
    width: 20px;
    height: 20px;
    border: 2px solid var(--text-secondary);
    border-radius: 50%;
    margin-right: 12px;
    outline: none;
    display: grid;
    place-content: center;
    cursor: pointer;
}

input[type="radio"]::before {
    content: "";
    width: 10px;
    height: 10px;
    border-radius: 50%;
    transform: scale(0);
    transition: 120ms transform ease-in-out;
    background-color: var(--accent-color);
}

input[type="radio"]:checked {
    border-color: var(--accent-color);
}

input[type="radio"]:checked::before {
    transform: scale(1);
}

input[type="radio"]:focus-visible {
    outline: var(--focus-outline);
    outline-offset: 4px;
}

label {
    cursor: pointer;
    font-size: 1rem;
    flex-grow: 1;
}

.error-message {
    color: var(--error-color);
    font-size: 0.875rem;
    margin-top: 0.5rem;
    display: block;
}

.form-actions {
    margin-top: 1rem;
}

button {
    background-color: var(--accent-color);
    color: #000;
    border: none;
    padding: 0.75rem 1.5rem;
    font-size: 1rem;
    font-weight: 600;
    border-radius: 4px;
    cursor: pointer;
    transition: background-color 0.2s, transform 0.1s;
    width: 100%;
}

button:hover {
    background-color: var(--accent-hover);
}

button:active {
    transform: translateY(1px);
}

button:focus-visible {
    outline: var(--focus-outline);
    outline-offset: 4px;
}
