<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Notification Preferences</title>
    <style>
        :root {
            --bg-color: #121212;
            --container-bg: #1e1e1e;
            --text-primary: #e0e0e0;
            --text-secondary: #b0b0b0;
            --accent-color: #bb86fc;
            --accent-hover: #a370f7;
            --error-color: #cf6679;
            --border-color: #333333;
            --focus-outline: 2px solid #bb86fc;
        }

        * {
            box-sizing: border-box;
        }

        body {
            background-color: var(--bg-color);
            color: var(--text-primary);
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
            margin: 0;
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
        }

        .sr-only:not(:focus):not(:active) {
            clip: rect(0 0 0 0);
            clip-path: inset(50%);
            height: 1px;
            overflow: hidden;
            position: absolute;
            white-space: nowrap;
            width: 1px;
        }

        .skip-link {
            position: absolute;
            top: 1rem;
            left: 1rem;
            background: var(--accent-color);
            color: #000;
            padding: 0.5rem 1rem;
            text-decoration: none;
            font-weight: bold;
            border-radius: 4px;
            z-index: 100;
        }

        .container {
            background-color: var(--container-bg);
            padding: 2rem;
            border-radius: 8px;
            box-shadow: 0 4px 20px rgba(0, 0, 0, 0.5);
            width: 100%;
            max-width: 450px;
        }

        h1 {
            margin-top: 0;
            font-size: 1.5rem;
            color: var(--accent-color);
        }

        .form-field {
            margin-bottom: 2rem;
        }

        fieldset {
            border: none;
            padding: 0;
            margin: 0;
        }

        legend {
            font-size: 1.1rem;
            font-weight: 600;
            margin-bottom: 0.5rem;
            display: block;
        }

        .required {
            color: var(--error-color);
            margin-left: 0.25rem;
        }

        .field-hint {
            font-size: 0.9rem;
            color: var(--text-secondary);
            margin-bottom: 1rem;
        }

        .radio-options {
            display: flex;
            flex-direction: column;
            gap: 0.5rem;
        }

        .radio-option {
            display: flex;
            align-items: center;
            border-radius: 4px;
            transition: background-color 0.2s;
            position: relative;
        }

        .radio-option:hover {
            background-color: rgba(255, 255, 255, 0.05);
        }

        input[type="radio"] {
            appearance: none;
            -webkit-appearance: none;
            width: 20px;
            height: 20px;
            border: 2px solid var(--text-secondary);
            border-radius: 50%;
            margin: 12px;
            outline: none;
            display: grid;
            place-content: center;
            cursor: pointer;
            flex-shrink: 0;
        }

        input[type="radio"]::before {
            content: "";
            width: 10px;
            height: 10px;
            border-radius: 50%;
            transform: scale(0);
            transition: 120ms transform ease-in-out;
            background-color: var(--accent-color);
        }

        input[type="radio"]:checked {
            border-color: var(--accent-color);
        }

        input[type="radio"]:checked::before {
            transform: scale(1);
        }

        input[type="radio"]:focus-visible {
            outline: var(--focus-outline);
            outline-offset: 4px;
        }

        label {
            cursor: pointer;
            font-size: 1rem;
            padding: 12px 12px 12px 0;
            flex-grow: 1;
            display: block;
        }

        /* Support for browsers that don't support :has */
        .radio-option:focus-within {
            background-color: rgba(255, 255, 255, 0.05);
        }

        .error-message {
            color: var(--error-color);
            font-size: 0.875rem;
            margin-top: 1rem;
            font-weight: 500;
        }

        .form-actions {
            margin-top: 1rem;
        }

        button {
            background-color: var(--accent-color);
            color: #000;
            border: none;
            padding: 0.75rem 1.5rem;
            font-size: 1rem;
            font-weight: 600;
            border-radius: 4px;
            cursor: pointer;
            transition: background-color 0.2s, transform 0.1s;
            width: 100%;
        }

        button:hover {
            background-color: var(--accent-hover);
        }

        button:active {
            transform: translateY(1px);
        }

        button:focus-visible {
            outline: var(--focus-outline);
            outline-offset: 4px;
        }

        #main-content:focus {
            outline: none;
        }
    </style>
</head>
<body>
    <a href="#main-content" class="skip-link sr-only">Skip to main content</a>
    <main id="main-content" tabindex="-1">
        <section class="container">
            <h1>Notification Settings</h1>
            <form id="preferences-form" novalidate>
                <div class="form-field">
                    <fieldset id="notification-method-group" aria-describedby="notification-hint">
                        <legend>How do you prefer to receive notifications? <span class="required" aria-hidden="true">*</span></legend>
                        <p class="field-hint" id="notification-hint">Select the primary channel we should use to reach you.</p>

                        <div class="radio-options">
                            <div class="radio-option">
                                <input type="radio" id="method-email" name="notification-method" value="email" required>
                                <label for="method-email">Email</label>
                            </div>

                            <div class="radio-option">
                                <input type="radio" id="method-sms" name="notification-method" value="sms" required>
                                <label for="method-sms">SMS</label>
                            </div>

                            <div class="radio-option">
                                <input type="radio" id="method-push" name="notification-method" value="push" required>
                                <label for="method-push">Push Notifications</label>
                            </div>
                        </div>

                        <div id="error-message" class="error-message" hidden>
                            Error: Please select a notification method.
                        </div>
                    </fieldset>
                </div>

                <div class="form-actions">
                    <button type="submit">Save Preferences</button>
                </div>
            </form>
        </section>
    </main>
    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const form = document.getElementById('preferences-form');
            const fieldset = document.getElementById('notification-method-group');
            const radios = form.querySelectorAll('input[name="notification-method"]');
            const errorMessage = document.getElementById('error-message');

            form.addEventListener('submit', (event) => {
                event.preventDefault();

                const selectedRadio = form.querySelector('input[name="notification-method"]:checked');

                if (selectedRadio) {
                    errorMessage.hidden = true;
                    fieldset.removeAttribute('aria-invalid');
                    fieldset.setAttribute('aria-describedby', 'notification-hint');

                    alert(`Preferences saved! You chose: ${selectedRadio.value}`);
                } else {
                    errorMessage.hidden = false;
                    fieldset.setAttribute('aria-invalid', 'true');
                    fieldset.setAttribute('aria-describedby', 'notification-hint error-message');

                    // Focus the first radio button
                    radios[0].focus();
                }
            });

            radios.forEach(radio => {
                radio.addEventListener('change', () => {
                    if (radio.checked) {
                        errorMessage.hidden = true;
                        fieldset.removeAttribute('aria-invalid');
                        fieldset.setAttribute('aria-describedby', 'notification-hint');
                    }
                });
            });
        });
    </script>
</body>
</html>
